"""Skyline Billboard

A city streetscape consists of a row of buildings with given heights.
The city wants to place a rectangular billboard that sits on the ground (height 0) and is as wide as the number of consecutive buildings it spans.
The billboard's height cannot exceed the smallest building in that segment.
Find the maximum possible area of such a billboard.
"""
import unittest

def maxBillboardArea(heights):
    """Return the maximum possible billboard area.

    Start with a billboard that covers the entire range.
    We can store the heights in a sorted list so we always know the smallest height in the range.
    Reduce the range by one, moving in the smallest edge.
    Remove that height from the range to update the smallest height.
    """
    start, end = 0, len(heights) - 1
    h = sorted(heights, reverse=True)
    best = 0
    while start <= end:
        best = max(best, (end - start + 1) * h[-1])
        if heights[start] < heights[end]:
            h.remove(heights[start])
            start += 1
        else:
            h.remove(heights[end])
            end -= 1
    return best


class TestSolution(unittest.TestCase):
    def test_data(self):
        self.assertEqual(maxBillboardArea([2, 1, 5, 6, 2, 3]), 10)
        self.assertEqual(maxBillboardArea([1]), 1)
        self.assertEqual(maxBillboardArea([2, 2, 2]), 6)
